24	// TestProcessDispatchesDecodedEvent: a payload that decodes reaches handle with the
25	// decoded event and a live span; the message is left for handle to ack/nak (Process
26	// does not touch it), and onUndecodable is not called.
27	func TestProcessDispatchesDecodedEvent(t *testing.T) {
28		msg := &natsmsgtest.FakeMsg{DataVal: []byte("payload")}
29		var (
30			gotEv   string
31			gotSpan trace.Span
32			gotMsg  jetstream.Msg
33			dropped bool
34		)
35		decode := func(b []byte) (string, error) { return "decoded:" + string(b), nil }
36		handle := func(_ context.Context, span trace.Span, m jetstream.Msg, ev string) {
37			gotEv, gotSpan, gotMsg = ev, span, m
38		}
39		Process(context.Background(), msg, testCfg, decode, handle, func(context.Context) { dropped = true })
40	
41		if gotEv != "decoded:payload" {
42			t.Errorf("handle got ev %q, want decoded:payload", gotEv)
43		}
44		if gotSpan == nil {
45			t.Error("handle got a nil span, want the live consumer span")
46		}
47		if gotMsg != msg {
48			t.Error("handle got a different msg than the one passed to Process")
49		}
50		if msg.Acked || msg.Termed || msg.Naks > 0 || len(msg.NakDelays) > 0 {
51			t.Error("Process disposed the message, want none (handle owns ack/nak)")
52		}
53		if dropped {
54			t.Error("onUndecodable called on a successful decode")
55		}
56	}
