58	// TestProcessTermsUndecodable: a decode error terms the message, bumps the caller's
59	// drop metric via onUndecodable, and never calls handle — a poison payload won't
60	// decode on redelivery.
61	func TestProcessTermsUndecodable(t *testing.T) {
62		msg := &natsmsgtest.FakeMsg{DataVal: []byte("garbage")}
63		handled := false
64		dropped := false
65		decode := func([]byte) (string, error) { return "", errors.New("bad payload") }
66		handle := func(context.Context, trace.Span, jetstream.Msg, string) { handled = true }
67		Process(context.Background(), msg, testCfg, decode, handle, func(context.Context) { dropped = true })
68	
69		if !msg.Termed {
70			t.Error("message not termed on a decode error")
71		}
72		if !dropped {
73			t.Error("onUndecodable not called on a decode error")
74		}
75		if handled {
76			t.Error("handle called despite a decode error")
77		}
78	}
