91	// TestProcessKeepInProgress: with Config.KeepInProgress set, a handler that
92	// outruns AckWait/3 gets InProgress heartbeats, and the heartbeat goroutine has
93	// stopped by the time Process returns (no further ticks accrue).
94	func TestProcessKeepInProgress(t *testing.T) {
95		cfg := testCfg
96		cfg.KeepInProgress = true
97		cfg.AckWait = 30 * time.Millisecond // ticks at 10ms
98	
99		msg := &natsmsgtest.FakeMsg{DataVal: []byte("payload")}
100		decode := func(b []byte) (string, error) { return string(b), nil }
101		handle := func(context.Context, trace.Span, jetstream.Msg, string) {
102			time.Sleep(35 * time.Millisecond) // spans at least three ticks
103		}
104		Process(context.Background(), msg, cfg, decode, handle, nil)
105	
106		after := msg.InProgressN
107		if after == 0 {
108			t.Fatal("no InProgress heartbeat during a long handler")
109		}
110		time.Sleep(25 * time.Millisecond)
111		if msg.InProgressN != after {
112			t.Errorf("heartbeat still ticking after Process returned: %d → %d", after, msg.InProgressN)
113		}
114	}
