134	// TestConfigEffectiveValues pins the zero-value resolution callers must use
135	// when the real tunables matter outside the scaffold — most importantly
136	// feeding EffectiveMaxDeliver (never the raw field) into a backoff.Policy,
137	// where a zero means unlimited redeliveries instead of "default to 8".
138	func TestConfigEffectiveValues(t *testing.T) {
139		var zero Config
140		if got := zero.EffectiveAckWait(); got != DefaultAckWait {
141			t.Errorf("zero EffectiveAckWait = %v, want DefaultAckWait (%v)", got, DefaultAckWait)
142		}
143		if got := zero.EffectiveMaxDeliver(); got != DefaultMaxDeliver {
144			t.Errorf("zero EffectiveMaxDeliver = %d, want DefaultMaxDeliver (%d)", got, DefaultMaxDeliver)
145		}
146		set := Config{AckWait: time.Second, MaxDeliver: 3}
147		if got := set.EffectiveAckWait(); got != time.Second {
148			t.Errorf("set EffectiveAckWait = %v, want 1s", got)
149		}
150		if got := set.EffectiveMaxDeliver(); got != 3 {
151			t.Errorf("set EffectiveMaxDeliver = %d, want 3", got)
152		}
153	}
