155	// TestEffectiveMaxDeliverComposesWithBackoff pins the documented bridge between
156	// the two packages' MaxDeliver conventions: jsconsumer reads 0 as "default to
157	// DefaultMaxDeliver", backoff reads <=0 as unlimited (the jetstream.ConsumerConfig
158	// semantics). Feeding EffectiveMaxDeliver() — never the raw field — into a
159	// backoff.Policy is what keeps an unset consumer MaxDeliver finite in the policy
160	// instead of accidentally unlimited (which would make TermOnExhaustion never
161	// fire and orphan work-queue messages, COR-762).
162	func TestEffectiveMaxDeliverComposesWithBackoff(t *testing.T) {
163		delivered := func(n uint64) *natsmsgtest.FakeMsg {
164			return &natsmsgtest.FakeMsg{Meta: &jetstream.MsgMetadata{NumDelivered: n}}
165		}
166		for _, tc := range []struct {
167			name          string
168			cfg           Config
169			wantEffective int
170			finalAt       uint64 // delivery that should read as final; 0 => never final (unlimited)
171		}{
172			{"unset defaults to DefaultMaxDeliver", Config{}, DefaultMaxDeliver, DefaultMaxDeliver},
173			{"positive passes through", Config{MaxDeliver: 3}, 3, 3},
174			{"unlimited -1 stays unlimited", Config{MaxDeliver: -1}, -1, 0},
175		} {
176			t.Run(tc.name, func(t *testing.T) {
177				eff := tc.cfg.EffectiveMaxDeliver()
178				if eff != tc.wantEffective {
179					t.Fatalf("EffectiveMaxDeliver = %d, want %d", eff, tc.wantEffective)
180				}
181				policy := backoff.Policy{MaxDeliver: eff}
182				if tc.finalAt == 0 {
183					if backoff.IsFinalDelivery(delivered(1000), policy.MaxDeliver) {
184						t.Error("unlimited policy read a delivery as final")
185					}
186					return
187				}
188				if backoff.IsFinalDelivery(delivered(tc.finalAt-1), policy.MaxDeliver) {
189					t.Errorf("delivery %d/%d read as final", tc.finalAt-1, eff)
190				}
191				if !backoff.IsFinalDelivery(delivered(tc.finalAt), policy.MaxDeliver) {
192					t.Errorf("delivery %d/%d not read as final", tc.finalAt, eff)
193				}
194			})
195		}
196	}
