292	// TestIsShutdownConsumeErr pins the classifier over BOTH error families: the
293	// jetstream consume loop emits its own jetstream.ErrConnectionClosed (a
294	// distinct value wrapping neither core sentinel), and either family is benign
295	// only once ctx is done — a mid-run connection loss stays a real fault.
296	func TestIsShutdownConsumeErr(t *testing.T) {
297		done, cancel := context.WithCancel(context.Background())
298		cancel()
299		live := context.Background()
300	
301		for _, tc := range []struct {
302			name string
303			ctx  context.Context
304			err  error
305			want bool
306		}{
307			{"jetstream closed, shutting down", done, jetstream.ErrConnectionClosed, true},
308			{"core closed, shutting down", done, nats.ErrConnectionClosed, true},
309			{"core draining, shutting down", done, nats.ErrConnectionDraining, true},
310			{"jetstream closed, mid-run", live, jetstream.ErrConnectionClosed, false},
311			{"unrelated error, shutting down", done, errors.New("boom"), false},
312		} {
313			if got := isShutdownConsumeErr(tc.ctx, tc.err); got != tc.want {
314				t.Errorf("%s: isShutdownConsumeErr = %v, want %v", tc.name, got, tc.want)
315			}
316		}
317	}
