333	// startTestConsumer boots an embedded JetStream server, a stream, and a
334	// running consumer delivering to onMsg, returning the runner, the JetStream
335	// context for publishing, and the consume context's cancel.
336	func startTestConsumer(t *testing.T, onMsg func(jetstream.Msg)) (*Runner, jetstream.JetStream, context.CancelFunc) {
337		t.Helper()
338		url := runJetStreamServer(t)
339		nc, err := nats.Connect(url)
340		if err != nil {
341			t.Fatalf("connect: %v", err)
342		}
343		t.Cleanup(nc.Close)
344	
345		js, err := jetstream.New(nc)
346		if err != nil {
347			t.Fatalf("jetstream.New: %v", err)
348		}
349		ctx, cancel := context.WithCancel(context.Background())
350		t.Cleanup(cancel)
351		if _, err := js.CreateStream(ctx, jetstream.StreamConfig{
352			Name: "events_v1", Subjects: []string{"events.>"},
353		}); err != nil {
354			t.Fatalf("create stream: %v", err)
355		}
356		run, err := Start(ctx, nc, Config{
357			Stream:        "events_v1",
358			Durable:       "test_durable",
359			FilterSubject: "events.repo",
360			Name:          "testconsumer",
361			SpanName:      "test.consume",
362		}, onMsg)
363		if err != nil {
364			t.Fatalf("Start: %v", err)
365		}
366		return run, js, cancel
