369	// TestStopWaitsForInFlightHandler pins Stop's join semantics: it must not
370	// return while a handler is mid-flight, so callers can tear down the
371	// resources handlers use (stores, publishers, the connection) as soon as it
372	// returns — the cancel → join → drain ordering.
373	func TestStopWaitsForInFlightHandler(t *testing.T) {
374		started := make(chan struct{})
375		var handlerDone atomic.Bool
376		run, js, _ := startTestConsumer(t, func(m jetstream.Msg) {
377			close(started)
378			time.Sleep(300 * time.Millisecond)
379			handlerDone.Store(true)
380			if err := m.Ack(); err != nil {
381				t.Errorf("ack: %v", err)
382			}
383		})
384	
385		if _, err := js.Publish(context.Background(), "events.repo", []byte("slow")); err != nil {
386			t.Fatalf("publish: %v", err)
387		}
388		select {
389		case <-started:
390		case <-time.After(5 * time.Second):
391			t.Fatal("handler never started")
392		}
393		run.Stop()
394		if !handlerDone.Load() {
395			t.Fatal("Stop returned while the handler was still in flight")
396		}
397	}
