399	// TestStopConcurrentWithCancel drives the explicit-Stop-races-context-cancel
400	// path the race detector previously caught: several goroutines call Stop
401	// while ctx cancellation triggers the Start-armed stop. All calls must
402	// return, without panic or race.
403	func TestStopConcurrentWithCancel(t *testing.T) {
404		run, _, cancel := startTestConsumer(t, func(jetstream.Msg) {})
405	
406		var wg sync.WaitGroup
407		for range 8 {
408			wg.Add(1)
409			go func() {
410				defer wg.Done()
411				run.Stop()
412			}()
413		}
414		cancel()
415		done := make(chan struct{})
416		go func() { wg.Wait(); close(done) }()
417		select {
418		case <-done:
419		case <-time.After(10 * time.Second):
420			t.Fatal("concurrent Stop calls did not all return")
421		}
422	}
