	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
)

func srv(t *testing.T) string {
	t.Helper()
	s, err := natsserver.NewServer(&natsserver.Options{
		Host: "127.0.0.1", Port: -1, NoLog: true, NoSigs: true,
		JetStream: true, StoreDir: t.TempDir(),
	})
	if err != nil {
		t.Fatal(err)
	}
	go s.Start()
	if !s.ReadyForConnections(10 * time.Second) {
		t.Fatal("not ready")
	}
	t.Cleanup(s.Shutdown)
	return s.ClientURL()
}

func env(t *testing.T) (*nats.Conn, jetstream.JetStream) {
	t.Helper()
	nc, err := nats.Connect(srv(t))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(nc.Close)
	js, err := jetstream.New(nc)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{Name: "s", Subjects: []string{"s.>"}}); err != nil {
		t.Fatal(err)
	}
	return nc, js
}

// Probe 1: ladder gaps with a growing BackOff and MaxDeliver > len(BackOff).
func TestProbeLadderGaps(t *testing.T) {
	_, js := env(t)
	cons, err := js.CreateConsumer(t.Context(), "s", jetstream.ConsumerConfig{
		Durable:    "d",
		AckPolicy:  jetstream.AckExplicitPolicy,
		AckWait:    200 * time.Millisecond,
		BackOff:    []time.Duration{200 * time.Millisecond, 600 * time.Millisecond},
		MaxDeliver: 5,
	})
	if err != nil {
		t.Fatal(err)
	}
	info, _ := cons.Info(t.Context())
	b, _ := json.Marshal(info.Config)
	t.Logf("stored config: %s", b)

	if _, err := js.Publish(t.Context(), "s.a", []byte("x")); err != nil {
		t.Fatal(err)
	}
	var last time.Time
	var gaps []time.Duration
	cc, err := cons.Consume(func(m jetstream.Msg) {
		now := time.Now()
		md, _ := m.Metadata()
		if !last.IsZero() {
			gaps = append(gaps, now.Sub(last))
		}
		last = now
		t.Logf("delivery %d at +%v", md.NumDelivered, now.Sub(last))
		// do nothing: let AckWait/backoff drive redelivery
	})
	if err != nil {
		t.Fatal(err)
	}
	defer cc.Stop()
	time.Sleep(3 * time.Second)
	t.Logf("gaps (no disposition): %v", gaps)
	i, _ := cons.Info(t.Context())
	t.Logf("delivered=%+v ackfloor=%+v numAckPending=%d numRedelivered=%d", i.Delivered, i.AckFloor, i.NumAckPending, i.NumRedelivered)
}

// Probe 2: NakWithDelay under a growing ladder — is the requested delay honored,
// or stretched by (BackOff[dc] - BackOff[0])?
func TestProbeNakDelayStretch(t *testing.T) {
	_, js := env(t)
	cons, err := js.CreateConsumer(t.Context(), "s", jetstream.ConsumerConfig{
		Durable:    "d",
		AckPolicy:  jetstream.AckExplicitPolicy,
		AckWait:    200 * time.Millisecond,
		BackOff:    []time.Duration{200 * time.Millisecond, 1200 * time.Millisecond},
		MaxDeliver: 4,
	})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := js.Publish(t.Context(), "s.a", []byte("x")); err != nil {
		t.Fatal(err)
	}
	var last time.Time
	type obs struct {
		n   uint64
		gap time.Duration
	}
	var got []obs
	cc, err := cons.Consume(func(m jetstream.Msg) {
		now := time.Now()
		md, _ := m.Metadata()
		if !last.IsZero() {
			got = append(got, obs{md.NumDelivered, now.Sub(last)})
		}
		last = now
		// Always Nak with a tiny delay: 50ms requested.
		_ = m.NakWithDelay(50 * time.Millisecond)
	})
	if err != nil {
		t.Fatal(err)
	}
	defer cc.Stop()
	time.Sleep(4 * time.Second)
	t.Logf("NakWithDelay(50ms) observed gaps: %+v", got)
}

