// Probe 4: Term on a limits stream — does the ack floor advance? Does the message leave?
func TestProbeTermSettles(t *testing.T) {
	_, js := env(t)
	for _, retention := range []jetstream.RetentionPolicy{jetstream.LimitsPolicy, jetstream.WorkQueuePolicy, jetstream.InterestPolicy} {
		t.Run(fmt.Sprint(retention), func(t *testing.T) {
			nc, err := nats.Connect(srv(t))
			if err != nil {
				t.Fatal(err)
			}
			defer nc.Close()
			js2, _ := jetstream.New(nc)
			st, err := js2.CreateStream(t.Context(), jetstream.StreamConfig{
				Name: "t", Subjects: []string{"t.>"}, Retention: retention,
			})
			if err != nil {
				t.Fatal(err)
			}
			cons, err := js2.CreateConsumer(t.Context(), "t", jetstream.ConsumerConfig{
				Durable: "d", AckPolicy: jetstream.AckExplicitPolicy, AckWait: 10 * time.Second,
			})
			if err != nil {
				t.Fatal(err)
			}
			for range 3 {
				if _, err := js2.Publish(t.Context(), "t.a", []byte("x")); err != nil {
					t.Fatal(err)
				}
			}
			batch, err := cons.Fetch(3)
			if err != nil {
				t.Fatal(err)
			}
			n := 0
			for m := range batch.Messages() {
				n++
				if n == 1 {
					if err := m.Term(); err != nil {
						t.Fatal(err)
					}
				} else {
					if err := m.Ack(); err != nil {
						t.Fatal(err)
					}
				}
			}
			time.Sleep(300 * time.Millisecond)
			ci, _ := cons.Info(t.Context())
			si, _ := st.Info(t.Context())
			t.Logf("retention=%v ackfloor=%+v delivered=%+v pending=%d | stream msgs=%d firstseq=%d lastseq=%d",
