			raw, err := st.GetMsg(t.Context(), 1)
			if err != nil {
				t.Logf("GetMsg(1) after Term: %v", err)
			} else {
				t.Logf("GetMsg(1) after Term: present, subject=%s", raw.Subject)
			}
		})
	}
}

