	cons, err := js.CreateConsumer(t.Context(), "f", jetstream.ConsumerConfig{
		Durable: "d", AckPolicy: jetstream.AckExplicitPolicy,
		FilterSubject: "f.keep", AckWait: 500 * time.Millisecond, MaxDeliver: 20,
	})
	if err != nil {
		t.Fatal(err)
	}
	// interleave: keep=1, skip=2, keep=3, skip=4, keep=5
	for _, s := range []string{"f.keep", "f.skip", "f.keep", "f.skip", "f.keep"} {
		if _, err := js.Publish(t.Context(), s, []byte("x")); err != nil {
			t.Fatal(err)
		}
	}
	batch, err := cons.Fetch(3)
	if err != nil {
		t.Fatal(err)
	}
	var seqs []uint64
	for m := range batch.Messages() {
		md, _ := m.Metadata()
		seqs = append(seqs, md.Sequence.Stream)
		if md.Sequence.Stream != 3 { // leave stream seq 3 unacked (the blocker)
			if err := m.Ack(); err != nil {
				t.Fatal(err)
			}
		}
	}
	t.Logf("fetched stream seqs %v; left 3 unacked", seqs)
	time.Sleep(200 * time.Millisecond)
	i, _ := cons.Info(t.Context())
	t.Logf("BEFORE drain: ackfloor=%+v delivered=%+v pending=%d redelivered=%d numPending=%d",
		i.AckFloor, i.Delivered, i.NumAckPending, i.NumRedelivered, i.NumPending)
	t.Logf("  AckFloor.Stream+1 = %d (blocker is 3?) AckFloor.Consumer+1 = %d", i.AckFloor.Stream+1, i.AckFloor.Consumer+1)

	// let it redeliver a few times, then look again
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		b, err := cons.Fetch(1, jetstream.FetchMaxWait(300*time.Millisecond))
		if err != nil {
			continue
		}
		for m := range b.Messages() {
			md, _ := m.Metadata()
			t.Logf("  redelivery: stream seq %d, numDelivered %d, consumer seq %d", md.Sequence.Stream, md.NumDelivered, md.Sequence.Consumer)
		}
	}
	i2, _ := cons.Info(t.Context())
	t.Logf("AFTER redeliveries: ackfloor=%+v delivered=%+v pending=%d redelivered=%d",
		i2.AckFloor, i2.Delivered, i2.NumAckPending, i2.NumRedelivered)
	t.Logf("  AckFloor.Stream+1 = %d  AckFloor.Consumer+1 = %d", i2.AckFloor.Stream+1, i2.AckFloor.Consumer+1)
}

// Probe 8: can Ack()/Term() silently succeed when the client has no $JS.ACK publish
// permission (COR-1224 shape), while DoubleAck surfaces it?
func TestProbeAckWithoutPermission(t *testing.T) {
	opts := &natsserver.Options{
		Host: "127.0.0.1", Port: -1, NoLog: true, NoSigs: true,
		JetStream: true, StoreDir: t.TempDir(),
		Users: []*natsserver.User{{
			Username: "app", Password: "pw",
			Permissions: &natsserver.Permissions{
				Publish: &natsserver.SubjectPermission{
					Allow: []string{"$JS.API.>", "p.>"},
					// deliberately no $JS.ACK.>
				},
				Subscribe: &natsserver.SubjectPermission{Allow: []string{"_INBOX.>", ">"}},
			},
		}},
	}
	s, err := natsserver.NewServer(opts)
	if err != nil {
		t.Fatal(err)
	}
	go s.Start()
	if !s.ReadyForConnections(10 * time.Second) {
		t.Fatal("not ready")
	}
	t.Cleanup(s.Shutdown)

	var asyncErrs []error
	nc, err := nats.Connect(s.ClientURL(), nats.UserInfo("app", "pw"),
		nats.ErrorHandler(func(_ *nats.Conn, _ *nats.Subscription, e error) {
			asyncErrs = append(asyncErrs, e)
		}))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(nc.Close)
	js, err := jetstream.New(nc)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{Name: "p", Subjects: []string{"p.>"}}); err != nil {
		t.Fatal(err)
	}
	cons, err := js.CreateOrUpdateConsumer(t.Context(), "p", jetstream.ConsumerConfig{
		Durable: "d", AckPolicy: jetstream.AckExplicitPolicy, AckWait: 30 * time.Second,
	})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := js.Publish(t.Context(), "p.a", []byte("x")); err != nil {
		t.Fatal(err)
	}
	batch, err := cons.Fetch(1)
	if err != nil {
		t.Fatal(err)
	}
	for m := range batch.Messages() {
		err := m.Ack()
		t.Logf("Ack() with no $JS.ACK permission returned: %v", err)
	}
	time.Sleep(300 * time.Millisecond)
	i, _ := cons.Info(t.Context())
	t.Logf("after Ack: ackfloor=%+v pending=%d", i.AckFloor, i.NumAckPending)
	t.Logf("async errors: %v", asyncErrs)

	// Now try DoubleAck on a redelivery.
	if _, err := js.Publish(t.Context(), "p.a", []byte("y")); err != nil {
		t.Fatal(err)
	}
	b2, err := cons.Fetch(1)
	if err != nil {
		t.Fatal(err)
	}
	for m := range b2.Messages() {
		err := m.DoubleAck(t.Context())
		t.Logf("DoubleAck() with no $JS.ACK permission returned: %v (is timeout: %v)", err, errors.Is(err, nats.ErrTimeout))
	}
}

// Probe 9: does an exhausted (MaxDeliver-reached) message stop counting as ack-pending
// while still pinning the floor?
func TestProbeExhaustedAccounting(t *testing.T) {
	_, js := env(t)
	cons, err := js.CreateConsumer(t.Context(), "s", jetstream.ConsumerConfig{
		Durable: "ex", AckPolicy: jetstream.AckExplicitPolicy,
		AckWait: 150 * time.Millisecond, MaxDeliver: 2, FilterSubject: "s.a",
	})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := js.Publish(t.Context(), "s.a", []byte("poison")); err != nil {
		t.Fatal(err)
	}
	if _, err := js.Publish(t.Context(), "s.a", []byte("later")); err != nil {
		t.Fatal(err)
	}
	// Deliver both; ack only the second.
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		b, err := cons.Fetch(2, jetstream.FetchMaxWait(200*time.Millisecond))
		if err != nil {
			continue
		}
		for m := range b.Messages() {
			md, _ := m.Metadata()
			if md.Sequence.Stream == 2 {
				_ = m.Ack()
			}
			t.Logf("delivery: seq=%d numDelivered=%d", md.Sequence.Stream, md.NumDelivered)
		}
	}
	i, _ := cons.Info(t.Context())
	t.Logf("exhausted: ackfloor=%+v delivered=%+v numAckPending=%d numRedelivered=%d numPending=%d",
		i.AckFloor, i.Delivered, i.NumAckPending, i.NumRedelivered, i.NumPending)
}

package probe

import (
	"testing"
	"time"

	"github.com/nats-io/nats.go/jetstream"
)

// Probe 10: floor jump when messages are removed underneath the consumer
// (retention / purge / operator `stream rmm` — the ENT-1535 break-glass).
func TestProbeFloorJumpAfterRemoval(t *testing.T) {
	_, js := env(t)
	st, err := js.CreateStream(t.Context(), jetstream.StreamConfig{Name: "r", Subjects: []string{"r.>"}})
	if err != nil {
		t.Fatal(err)
	}
	cons, err := js.CreateConsumer(t.Context(), "r", jetstream.ConsumerConfig{
		Durable: "d", AckPolicy: jetstream.AckExplicitPolicy,
		AckWait: 10 * time.Second, MaxDeliver: 50, FilterSubject: "r.keep",
	})
	if err != nil {
		t.Fatal(err)
	}
	for range 6 {
		if _, err := js.Publish(t.Context(), "r.keep", []byte("x")); err != nil {
			t.Fatal(err)
		}
	}
	// Deliver 1..6, ack none: all six pending, floor at 0.
	batch, err := cons.Fetch(6)
	if err != nil {
		t.Fatal(err)
	}
	n := 0
	for range batch.Messages() {
		n++
	}
	t.Logf("delivered %d, acked none", n)
	i0, _ := cons.Info(t.Context())
	t.Logf("before removal: ackfloor=%+v delivered=%+v pending=%d", i0.AckFloor, i0.Delivered, i0.NumAckPending)

	// Operator removes the first five (the ENT-1535 flow: delete the floor
	// boundary and the blocker).
	for seq := uint64(1); seq <= 5; seq++ {
		if err := st.DeleteMsg(t.Context(), seq); err != nil {
			t.Fatalf("delete %d: %v", seq, err)
		}
	}
	time.Sleep(500 * time.Millisecond)
	i1, _ := cons.Info(t.Context())
	t.Logf("after removing 1..5: ackfloor=%+v delivered=%+v pending=%d numPending=%d",
		i1.AckFloor, i1.Delivered, i1.NumAckPending, i1.NumPending)
	t.Logf("  AckFloor.Stream+1 = %d; seq 6 is still unacked", i1.AckFloor.Stream+1)

	// Now remove everything, including the last pending message.
	if err := st.DeleteMsg(t.Context(), 6); err != nil {
		t.Fatal(err)
	}
	time.Sleep(500 * time.Millisecond)
	i2, _ := cons.Info(t.Context())
	t.Logf("after removing all: ackfloor=%+v delivered=%+v pending=%d",
		i2.AckFloor, i2.Delivered, i2.NumAckPending)
	t.Logf("  AckFloor.Stream+1 = %d (no such message exists)", i2.AckFloor.Stream+1)
}

// Probe 11: no BackOff at all — does redelivery continue on repeated AckWait?
func TestProbeNoBackoffLadder(t *testing.T) {
	_, js := env(t)
	cons, err := js.CreateConsumer(t.Context(), "s", jetstream.ConsumerConfig{
		Durable: "nb", AckPolicy: jetstream.AckExplicitPolicy,
		AckWait: 200 * time.Millisecond, MaxDeliver: 4, FilterSubject: "s.a",
	})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := js.Publish(t.Context(), "s.a", []byte("x")); err != nil {
		t.Fatal(err)
	}
	var last time.Time
	var gaps []time.Duration
	cc, err := cons.Consume(func(m jetstream.Msg) {
		now := time.Now()
		if !last.IsZero() {
			gaps = append(gaps, now.Sub(last))
		}
		last = now
	})
	if err != nil {
		t.Fatal(err)
	}
	defer cc.Stop()
	time.Sleep(1500 * time.Millisecond)
	t.Logf("no-BackOff gaps with AckWait=200ms: %v", gaps)
}

// Probe 12: KeepInProgress — does InProgress actually reset the redelivery timer,
// and does a wedged handler still redeliver once the heartbeat stops?
func TestProbeInProgressExtends(t *testing.T) {
	_, js := env(t)
	cons, err := js.CreateConsumer(t.Context(), "s", jetstream.ConsumerConfig{
		Durable: "kip", AckPolicy: jetstream.AckExplicitPolicy,
		AckWait: 300 * time.Millisecond, MaxDeliver: 5, FilterSubject: "s.a",
	})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := js.Publish(t.Context(), "s.a", []byte("x")); err != nil {
		t.Fatal(err)
	}
	batch, err := cons.Fetch(1)
	if err != nil {
		t.Fatal(err)
	}
	for m := range batch.Messages() {
		// Heartbeat for ~900ms (3x AckWait) at AckWait/3.
		stop := make(chan struct{})
		go func() {
			tk := time.NewTicker(100 * time.Millisecond)
			defer tk.Stop()
			for {
				select {
				case <-stop:
					return
				case <-tk.C:
					if err := m.InProgress(); err != nil {
						t.Logf("InProgress err: %v", err)
					}
				}
			}
		}()
		time.Sleep(900 * time.Millisecond)
		i, _ := cons.Info(t.Context())
		t.Logf("while heartbeating (900ms > 3x AckWait): delivered=%+v redelivered=%d", i.Delivered, i.NumRedelivered)
		close(stop)
	}
	// Heartbeat stopped: AckWait expiry should redeliver.
	time.Sleep(600 * time.Millisecond)
	i2, _ := cons.Info(t.Context())
	t.Logf("after heartbeat stopped: delivered=%+v redelivered=%d", i2.Delivered, i2.NumRedelivered)
}

