package brokersemantics

import (
	"encoding/json"
	"fmt"
	"strings"
	"sync"
	"testing"
	"time"

	natsserver "github.com/nats-io/nats-server/v2/server"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
)

// The suite's own tunables. Ladder rungs are milliseconds rather than the
// minutes/hours of a production ladder: the arithmetic under test is scale-free,
// and the whole suite has to fit in a merge gate. They are still an order of
// magnitude above the broker's own timer granularity (ackWaitDelay is 1ms, and
// checkPending re-arms on the next rung), which is what keeps the measured gaps
// separable.
const (
	// shortAckWait is long enough that a delivery, a fetch round-trip and an
	// assertion fit inside it, short enough that a MaxDeliver ladder of them
	// finishes in a test.
	shortAckWait = 200 * time.Millisecond
	// settleWait is how long to let the server's pending timer and ack
	// bookkeeping catch up before reading ConsumerInfo.
	settleWait = 300 * time.Millisecond
	// waitTimeout bounds every wait-for-N-deliveries helper.
	waitTimeout = 15 * time.Second
)

// startServer boots an in-process JetStream nats-server — the version in go.mod,
// which is the whole point of the suite — on a random loopback port, and shuts it
// down when the test ends. opts may adjust the options (accounts, permissions,
// limits) before start.
func startServer(t *testing.T, opts ...func(*natsserver.Options)) *natsserver.Server {
	t.Helper()
	o := &natsserver.Options{
		Host:      "127.0.0.1",
		Port:      -1, // pick a free port
		NoLog:     true,
		NoSigs:    true,
		JetStream: true,
		StoreDir:  t.TempDir(),
	}
	for _, fn := range opts {
		fn(o)
	}
	s, err := natsserver.NewServer(o)
	if err != nil {
		t.Fatalf("new embedded nats server: %v", err)
	}
	go s.Start()
	if !s.ReadyForConnections(10 * time.Second) {
		t.Fatal("embedded nats server not ready in time")
	}
	t.Cleanup(s.Shutdown)
	return s
}

// connect dials s and closes the connection when the test ends. Async errors are
// recorded rather than logged to stderr, and returned by the drain func — the
// permissions tests read them, and a test that ignores them still gets them in
// its failure output.
func connect(t *testing.T, s *natsserver.Server, opts ...nats.Option) (*nats.Conn, func() []error) {
	t.Helper()
	var mu sync.Mutex
	var asyncErrs []error
	opts = append(opts, nats.ErrorHandler(func(_ *nats.Conn, _ *nats.Subscription, err error) {
		mu.Lock()
		asyncErrs = append(asyncErrs, err)
		mu.Unlock()
	}))
	nc, err := nats.Connect(s.ClientURL(), opts...)
	if err != nil {
		t.Fatalf("connect: %v", err)
	}
	t.Cleanup(nc.Close)
	return nc, func() []error {
		mu.Lock()
		defer mu.Unlock()
		return append([]error(nil), asyncErrs...)
	}
}

// env is the common setup: a fresh server, a connection, a JetStream handle, and
// a limits-retention stream named "events" over "events.>".
func env(t *testing.T) (*nats.Conn, jetstream.JetStream) {
	t.Helper()
	nc, _ := connect(t, startServer(t))
	js := jsHandle(t, nc)
	newStream(t, js, jetstream.StreamConfig{Name: "events", Subjects: []string{"events.>"}})
	return nc, js
}

func jsHandle(t *testing.T, nc *nats.Conn) jetstream.JetStream {
	t.Helper()
	js, err := jetstream.New(nc)
	if err != nil {
		t.Fatalf("jetstream.New: %v", err)
	}
	return js
}

func newStream(t *testing.T, js jetstream.JetStream, cfg jetstream.StreamConfig) jetstream.Stream {
	t.Helper()
	st, err := js.CreateStream(t.Context(), cfg)
	if err != nil {
		t.Fatalf("create stream %s: %v", cfg.Name, err)
	}
	return st
}

func newConsumer(t *testing.T, js jetstream.JetStream, stream string, cfg jetstream.ConsumerConfig) jetstream.Consumer {
	t.Helper()
	cons, err := js.CreateOrUpdateConsumer(t.Context(), stream, cfg)
	if err != nil {
		t.Fatalf("create consumer %s/%s: %v", stream, cfg.Durable, err)
	}
	return cons
}

func publish(t *testing.T, js jetstream.JetStream, subject string, payloads ...string) {
	t.Helper()
	for _, p := range payloads {
		if _, err := js.Publish(t.Context(), subject, []byte(p)); err != nil {
			t.Fatalf("publish %s: %v", subject, err)
		}
	}
}

func info(t *testing.T, cons jetstream.Consumer) *jetstream.ConsumerInfo {
	t.Helper()
	ci, err := cons.Info(t.Context())
	if err != nil {
		t.Fatalf("consumer info: %v", err)
	}
	return ci
}

// fetchAll pulls up to n messages and returns them, leaving their disposition to
// the caller. A short MaxWait keeps a test that expects fewer than n from
// stalling.
func fetchAll(t *testing.T, cons jetstream.Consumer, n int) []jetstream.Msg {
	t.Helper()
	batch, err := cons.Fetch(n, jetstream.FetchMaxWait(2*time.Second))
	if err != nil {
		t.Fatalf("fetch %d: %v", n, err)
	}
	var got []jetstream.Msg
	for m := range batch.Messages() {
		got = append(got, m)
	}
	if err := batch.Error(); err != nil {
		t.Fatalf("fetch %d: batch error: %v", n, err)
	}
	return got
}

// meta is the message's JetStream metadata, which every belief about delivery
// counting and sequencing is read from.
func meta(t *testing.T, m jetstream.Msg) *jetstream.MsgMetadata {
	t.Helper()
	md, err := m.Metadata()
	if err != nil {
		t.Fatalf("metadata: %v", err)
	}
	return md
}

// delivery is one observed delivery: which stream message, which delivery
// attempt, and when it arrived. Redelivery timing is asserted from the gaps
// between consecutive arrival times.
type delivery struct {
	streamSeq    uint64
	consumerSeq  uint64
	numDelivered uint64
	at           time.Time
}

func (d delivery) String() string {
	return fmt.Sprintf("{stream:%d consumer:%d delivered:%d}", d.streamSeq, d.consumerSeq, d.numDelivered)
}

// recorder collects deliveries from a consume callback. The callback runs on
// nats.go's goroutine, so every field is mutex-guarded.
type recorder struct {
	mu  sync.Mutex
	got []delivery
}

// record timestamps a delivery. Call it first in the callback, before any
// disposition, so the recorded time is arrival time and not handler time.
func (r *recorder) record(t *testing.T, m jetstream.Msg) delivery {
	t.Helper()
	md, err := m.Metadata()
	if err != nil {
		r.mu.Lock()
		defer r.mu.Unlock()
		t.Errorf("metadata in consume callback: %v", err)
		return delivery{}
	}
	d := delivery{
		streamSeq:    md.Sequence.Stream,
		consumerSeq:  md.Sequence.Consumer,
		numDelivered: md.NumDelivered,
		at:           time.Now(),
	}
	r.mu.Lock()
	r.got = append(r.got, d)
	r.mu.Unlock()
	return d
}

func (r *recorder) snapshot() []delivery {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]delivery(nil), r.got...)
}

// waitForN blocks until at least n deliveries have been recorded, then returns
// them. It fails the test rather than returning short, so callers can index the
// result.
func (r *recorder) waitForN(t *testing.T, n int) []delivery {
	t.Helper()
	deadline := time.Now().Add(waitTimeout)
	for time.Now().Before(deadline) {
		if got := r.snapshot(); len(got) >= n {
			return got
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("saw %v deliveries, want at least %d", r.snapshot(), n)
	return nil
}

// consume runs a consume loop for the test's duration, recording every delivery
// before handing the message to onMsg. onMsg may be nil, which is itself a
// disposition under test: "do nothing" is what a handler that dies, blocks, or
// deliberately declines to answer looks like to the broker.
func consume(t *testing.T, cons jetstream.Consumer, onMsg func(jetstream.Msg)) *recorder {
	t.Helper()
	r := &recorder{}
	cc, err := cons.Consume(func(m jetstream.Msg) {
		r.record(t, m)
		if onMsg != nil {
			onMsg(m)
		}
	}, jetstream.PullMaxMessages(1))
	if err != nil {
		t.Fatalf("consume: %v", err)
	}
	t.Cleanup(cc.Stop)
	return r
}

// gapsBetween returns the intervals between consecutive deliveries: gap i is the
// wait the server served BEFORE delivery i+2 (deliveries are 1-indexed), which is
// the form every ladder assertion is stated in.
func gapsBetween(ds []delivery) []time.Duration {
	var gaps []time.Duration
	for i := 1; i < len(ds); i++ {
		gaps = append(gaps, ds[i].at.Sub(ds[i-1].at))
	}
	return gaps
}

// Timing tolerances. The lower bound is tight — a redelivery that arrives
// materially early means the server used a different (usually smaller) rung, which
// is exactly the class of error the suite exists to catch. The upper bound is
// loose, because a busy CI box can delay a wakeup but cannot make one early.
const (
	gapEarlySlack = 40 * time.Millisecond
	gapLateSlack  = 500 * time.Millisecond
)

// assertGap pins an observed redelivery gap to the rung the server should have
// served. label names the wait ("before delivery 3") so a failure reads as a
// ladder position rather than an index.
func assertGap(t *testing.T, label string, got, want time.Duration) {
	t.Helper()
	low, high := want-gapEarlySlack, want+gapLateSlack
	if got < low || got > high {
		t.Errorf("%s: gap %v, want ~%v (band %v..%v)", label, got.Round(time.Millisecond), want, low, high)
	}
}

// assertImmediate pins a redelivery that must not wait on any ladder rung — the
// plain-Nak path, whose whole point is that it does not.
func assertImmediate(t *testing.T, label string, got time.Duration) {
	t.Helper()
	if got > 150*time.Millisecond {
		t.Errorf("%s: gap %v, want immediate redelivery (<150ms)", label, got.Round(time.Millisecond))
	}
}

// pedanticCreateConsumer creates a consumer through a hand-rolled JS API request
// with pedantic mode set, returning the API error the server replied with (nil on
// success). nats.go's jetstream package has no pedantic option — but NACK's
// controller drives consumer CRs through jsm.go, which sets it, so a fleet
// Consumer CR is validated under rules the ordinary client path never applies.
// Both paths are asserted, because a config that this module accepts and NACK
// rejects is a deployment that fails only in the cluster.
func pedanticCreateConsumer(t *testing.T, nc *nats.Conn, stream string, cfg jetstream.ConsumerConfig) *jetstream.APIError {
	t.Helper()
	req, err := json.Marshal(struct {
		Stream   string                    `json:"stream_name"`
		Config   jetstream.ConsumerConfig  `json:"config"`
		Action   string                    `json:"action,omitempty"`
		Pedantic bool                      `json:"pedantic"`
	}{Stream: stream, Config: cfg, Pedantic: true})
	if err != nil {
		t.Fatalf("marshal pedantic consumer request: %v", err)
	}
	name := cfg.Durable
	if name == "" {
		name = cfg.Name
	}
	reply, err := nc.Request(fmt.Sprintf("$JS.API.CONSUMER.CREATE.%s.%s", stream, name), req, 5*time.Second)
	if err != nil {
		t.Fatalf("pedantic consumer create request: %v", err)
	}
	var resp struct {
		Error *jetstream.APIError `json:"error"`
	}
	if err := json.Unmarshal(reply.Data, &resp); err != nil {
		t.Fatalf("unmarshal pedantic response %q: %v", reply.Data, err)
	}
	return resp.Error
}

// TestPinnedServerVersion records which server's semantics the rest of the suite
// measured, so a failure elsewhere is attributable to a version rather than to
// the machine it ran on. It asserts only that the linked server reports itself
// consistently — pinning a literal version here would turn every deliberate bump
// into a spurious failure, when the point of a bump is to re-run the suite and
// see which beliefs still hold.
func TestPinnedServerVersion(t *testing.T) {
	t.Parallel()
	_, js := env(t)
	cons := newConsumer(t, js, "events", jetstream.ConsumerConfig{
		Durable:   "version_probe",
		AckPolicy: jetstream.AckExplicitPolicy,
	})
	// The server stamps the version that created the consumer into its metadata,
	// which is the same field prod configs were read from in ENT-1492.
	got := info(t, cons).Config.Metadata["_nats.ver"]
	t.Logf("embedded nats-server VERSION=%s, consumer metadata _nats.ver=%s", natsserver.VERSION, got)
	if got == "" {
		t.Fatal("consumer metadata carries no _nats.ver; cannot attribute this suite's measurements to a server version")
	}
	if !strings.HasPrefix(natsserver.VERSION, got) && !strings.HasPrefix(got, natsserver.VERSION) {
		t.Errorf("linked server VERSION %q and consumer metadata _nats.ver %q disagree", natsserver.VERSION, got)
	}
}

package brokersemantics

import (
	"errors"
	"testing"
	"time"

	natsserver "github.com/nats-io/nats-server/v2/server"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"

	"github.com/entireio/go-nuts/natsmsg"
)

// TestTermSettlesAndAdvancesAckFloor is the ENT-1492 belief, measured.
//
// The belief under test — recorded in ENT-1492, in COR-944, and still carried in
// the fleet stream manifests as "a message leaves the stream only on a positive
// Ack: a Term or a MaxDeliver-exhausted Nak does NOT delete it (verified live on
// NATS 2.14.2)" — is that Term is not a settlement: the consumer's ack floor stays
// pinned behind a Term'd message.
//
// It does not reproduce. On every retention policy the Term settles the delivery
// immediately: the floor advances past the Term'd sequence and NumAckPending drops
// to zero. Running this same test against an embedded 2.14.2 (the version ENT-1492
// cites) gives identical results, so the belief is not a 2.14.2-vs-2.14.3
// difference either.
//
// What DOES differ by retention is whether the message leaves the stream, and that
// is the distinction the two issues conflate: on WorkQueue and Interest a Term
// removes it, on Limits it stays until the stream's own retention expires it. So
// backoff.Policy.TermOnExhaustion's promise — "a work-queue message is removed
// cleanly rather than orphaning un-acked" (COR-762) — holds; ENT-1492's premise
// for replacing Term with dead-letter-then-Ack does not. Dead-lettering remains
// right for a different and better reason: it keeps the payload (see
// TestDeadLetterCaptureThenAckSettlesAndPreservesProvenance).
func TestTermSettlesAndAdvancesAckFloor(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name            string
		retention       jetstream.RetentionPolicy
		wantMsgsInStrm  uint64
		wantTermedInStr bool
	}{
		{"limits keeps the message in the stream", jetstream.LimitsPolicy, 3, true},
		{"workqueue removes it", jetstream.WorkQueuePolicy, 0, false},
		{"interest removes it", jetstream.InterestPolicy, 0, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			nc, _ := connect(t, startServer(t))
			js := jsHandle(t, nc)
			st := newStream(t, js, jetstream.StreamConfig{
				Name: "poison", Subjects: []string{"poison.>"}, Retention: tc.retention,
			})
			cons := newConsumer(t, js, "poison", jetstream.ConsumerConfig{
				Durable:   "settler",
				AckPolicy: jetstream.AckExplicitPolicy,
				AckWait:   time.Minute, // long: no redelivery may confound the reading
			})
			publish(t, js, "poison.a", "one", "two", "three")

			// Term the head of line, Ack the rest: if Term did not settle, the
			// floor would stay at 0 with one message ack-pending.
			for _, m := range fetchAll(t, cons, 3) {
				if meta(t, m).Sequence.Stream == 1 {
					if err := m.Term(); err != nil {
						t.Fatalf("term: %v", err)
					}
					continue
				}
				if err := m.Ack(); err != nil {
					t.Fatalf("ack: %v", err)
				}
			}
			time.Sleep(settleWait)

			ci := info(t, cons)
			if ci.AckFloor.Stream != 3 {
				t.Errorf("ack floor at stream seq %d after Term+Ack, want 3: a Term left the floor pinned", ci.AckFloor.Stream)
			}
			if ci.NumAckPending != 0 {
				t.Errorf("NumAckPending = %d after Term+Ack, want 0: the Term'd delivery is still outstanding", ci.NumAckPending)
			}

			si, err := st.Info(t.Context())
			if err != nil {
				t.Fatalf("stream info: %v", err)
			}
			if si.State.Msgs != tc.wantMsgsInStrm {
				t.Errorf("stream holds %d messages after the Term, want %d", si.State.Msgs, tc.wantMsgsInStrm)
			}
			_, err = st.GetMsg(t.Context(), 1)
			switch {
			case tc.wantTermedInStr && err != nil:
				t.Errorf("Term'd message is gone from a %v stream: %v", tc.retention, err)
			case !tc.wantTermedInStr && err == nil:
				t.Errorf("Term'd message survives in a %v stream, want it removed", tc.retention)
			}
		})
	}
}

// TestDeadLetterCaptureThenAckSettlesAndPreservesProvenance drives
// natsmsg.DeadLetter against a real broker: the capture-then-Ack sequence the
// ENT-1492 fix adopted, and the one backoff's doc points callers to ("capture
// BEFORE disposing").
//
// The fake can show that DeadLetter published something. Only the broker can show
// the two things that matter operationally: the captured copy is durable in the
// DLQ stream with its Nats-Dlq-* provenance (so the poison payload survives the
// give-up, which is what the manual break-glass in ENT-1535 destroyed), and the
// Ack that follows advances the floor past the poison — the stall remedy itself.
func TestDeadLetterCaptureThenAckSettlesAndPreservesProvenance(t *testing.T) {
	t.Parallel()
	_, js := env(t)
	newStream(t, js, jetstream.StreamConfig{Name: "events_dlq", Subjects: []string{"events.dlq.>"}})
	cons := newConsumer(t, js, "events", jetstream.ConsumerConfig{
		Durable:       "capturer",
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       time.Minute,
		FilterSubject: "events.repo",
	})
	publish(t, js, "events.repo", "poison", "healthy")

	msgs := fetchAll(t, cons, 1)
	if len(msgs) != 1 {
		t.Fatalf("fetched %d messages, want 1", len(msgs))
	}
	poison := msgs[0]
	reason := natsmsg.SubjectToken("bad completion payload")
	if err := natsmsg.DeadLetter(t.Context(), js, "events.dlq."+reason, poison, "bad completion payload"); err != nil {
		t.Fatalf("DeadLetter: %v", err)
	}
	if err := poison.Ack(); err != nil {
		t.Fatalf("ack after capture: %v", err)
	}
	time.Sleep(settleWait)

	if got := info(t, cons).AckFloor.Stream; got != 1 {
		t.Errorf("ack floor at %d after capture-then-Ack, want 1 (the poison settled)", got)
	}

	// The captured copy must be readable from the DLQ stream, payload and
	// provenance intact — this is the record the break-glass path destroys.
	dlq, err := js.Stream(t.Context(), "events_dlq")
	if err != nil {
		t.Fatalf("dlq stream: %v", err)
	}
	captured, err := dlq.GetMsg(t.Context(), 1)
	if err != nil {
		t.Fatalf("read captured message: %v", err)
	}
	if string(captured.Data) != "poison" {
		t.Errorf("captured payload = %q, want %q", captured.Data, "poison")
	}
	for header, want := range map[string]string{
		natsmsg.DLQReasonHeader:    "bad completion payload",
		natsmsg.DLQOriginHeader:    "events.repo",
		natsmsg.DLQDeliveredHeader: "1",
		natsmsg.DLQStreamSeqHeader: "1",
	} {
		if got := captured.Header.Get(header); got != want {
			t.Errorf("captured %s = %q, want %q", header, got, want)
		}
	}
	if captured.Subject != "events.dlq."+reason {
		t.Errorf("captured on subject %q, want %q", captured.Subject, "events.dlq."+reason)
	}
}

// TestAckWithoutPublishPermissionSilentlySucceeds pins the sharpest edge in the
// whole disposition surface: Ack, Nak, Term and InProgress are fire-and-forget
// publishes to $JS.ACK.>, so a nil error is NOT evidence that the message
// settled. When the connection's identity lacks publish permission on $JS.ACK —
// the exact gap COR-1224 found on five webhooks_github_v1 consumers — the server
// rejects the ack, the floor stays pinned, and the client sees success. The only
// trace is an async error on the connection handler.
//
// This matters twice over. It is a mechanism that produces ENT-1492's symptom
// (a floor pinned for tens of hours with no redelivery and no log line) without
// requiring Term-does-not-settle to be true, which the test above shows it is
// not. And it qualifies backoff's own documentation: "a disposition error is
// worth a log line but nothing more" understates the failure, because on this
// path there is no error to log. A caller who must know the message settled has
// to use DoubleAck and treat its error as fatal.
func TestAckWithoutPublishPermissionSilentlySucceeds(t *testing.T) {
	t.Parallel()
	s := startServer(t, func(o *natsserver.Options) {
		o.Users = []*natsserver.User{{
			Username: "indexer", Password: "pw",
			Permissions: &natsserver.Permissions{
				// Everything a consumer needs EXCEPT $JS.ACK.> — the COR-1224 shape.
				Publish:   &natsserver.SubjectPermission{Allow: []string{"$JS.API.>", "events.>"}},
				Subscribe: &natsserver.SubjectPermission{Allow: []string{">"}},
			},
		}}
	})
	nc, asyncErrs := connect(t, s, nats.UserInfo("indexer", "pw"))
	js := jsHandle(t, nc)
	newStream(t, js, jetstream.StreamConfig{Name: "events", Subjects: []string{"events.>"}})
	cons := newConsumer(t, js, "events", jetstream.ConsumerConfig{
		Durable:   "denied",
		AckPolicy: jetstream.AckExplicitPolicy,
		AckWait:   time.Minute,
	})
	publish(t, js, "events.repo", "first", "second")

	msgs := fetchAll(t, cons, 1)
	if len(msgs) != 1 {
		t.Fatalf("fetched %d messages, want 1", len(msgs))
	}
	if err := msgs[0].Ack(); err != nil {
		t.Fatalf("Ack returned %v; this test's premise is that it returns nil even when denied", err)
	}
	time.Sleep(settleWait)

	ci := info(t, cons)
	if ci.AckFloor.Stream != 0 {
		t.Errorf("ack floor advanced to %d despite the denied ack, want 0", ci.AckFloor.Stream)
	}
	if ci.NumAckPending != 1 {
		t.Errorf("NumAckPending = %d, want 1: the delivery is still outstanding after the silent Ack", ci.NumAckPending)
	}
	// The rejection is observable only here — not on the Ack call.
	var sawViolation bool
	for _, err := range asyncErrs() {
		if errors.Is(err, nats.ErrPermissionViolation) {
			sawViolation = true
		}
	}
	if !sawViolation {
		t.Errorf("no permissions violation on the async error handler; saw %v", asyncErrs())
	}

	// DoubleAck is the surface that does report it: it waits for the server's
	// confirmation, which never comes. Note the error is the context's, not
	// nats.ErrTimeout — a caller classifying only nats sentinels will miss it.
	second := fetchAll(t, cons, 1)
	if len(second) != 1 {
		t.Fatalf("fetched %d messages on the second pull, want 1", len(second))
	}
	ctx, cancel := context.WithTimeout(t.Context(), 2*time.Second)
	defer cancel()
	err := second[0].DoubleAck(ctx)
	if err == nil {
		t.Fatal("DoubleAck succeeded without $JS.ACK publish permission, want an error")
	}
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Errorf("DoubleAck error = %v (%T), want a context deadline; callers matching only nats sentinels miss it", err, err)
	}
}

// TestExhaustedDeliveryPinsFloorWithNoAckPending pins the accounting signature of
// a message that has run out MaxDeliver without settling — the state ENT-1535's
// page was reading.
//
// Once the last delivery's AckWait expires the server stops redelivering, drops
// the message from NumAckPending, and leaves the ack floor pinned behind it
// forever (a limits stream keeps the message until max_age). So the operational
// reading is counter-intuitive twice: "Outstanding Acks: 0" does not mean nothing
// is outstanding, and a floor that is not moving is not evidence of an active
// retry ladder — the ladder may have finished hours ago.
//
// This is also the state backoff.Policy.TermOnExhaustion exists to avoid: without
// it, the final Nak is dropped by the broker and the message lands exactly here.
func TestExhaustedDeliveryPinsFloorWithNoAckPending(t *testing.T) {
	t.Parallel()
	_, js := env(t)
	cons := newConsumer(t, js, "events", jetstream.ConsumerConfig{
		Durable:       "exhauster",
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       shortAckWait,
		MaxDeliver:    2,
		FilterSubject: "events.repo",
	})
	publish(t, js, "events.repo", "poison", "healthy")

	// Never dispose of the poison; Ack everything behind it.
	r := consume(t, cons, func(m jetstream.Msg) {
		if string(m.Data()) != "poison" {
			if err := m.Ack(); err != nil {
				t.Errorf("ack: %v", err)
			}
		}
	})
	// Two deliveries of the poison (MaxDeliver=2) plus the healthy one.
	r.waitForN(t, 3)
	// Let the final AckWait expire so the server retires the delivery.
	time.Sleep(shortAckWait + settleWait)

	ci := info(t, cons)
	if ci.AckFloor.Stream != 0 {
		t.Errorf("ack floor = %d, want 0: an exhausted message must still pin the floor", ci.AckFloor.Stream)
	}
	if ci.NumAckPending != 0 {
		t.Errorf("NumAckPending = %d, want 0: an exhausted delivery stops counting as outstanding", ci.NumAckPending)
	}
	if ci.NumPending != 0 {
		t.Errorf("NumPending = %d, want 0: nothing is left undelivered", ci.NumPending)
	}
	if ci.Delivered.Stream != 2 {
		t.Errorf("Delivered.Stream = %d, want 2: delivery ran past the pinned floor", ci.Delivered.Stream)
	}
	// No further redelivery, however long we wait: MaxDeliver is spent.
	before := len(r.snapshot())
	time.Sleep(3 * shortAckWait)
	if after := len(r.snapshot()); after != before {
		t.Errorf("saw %d deliveries after exhaustion, want the %d already recorded", after, before)
	}
}

package brokersemantics

import (
	"testing"
	"time"

	"github.com/nats-io/nats.go/jetstream"

	"github.com/entireio/go-nuts/backoff"
)

// TestNumDeliveredInflatesWithoutHandlerInvolvement pins what NumDelivered
// actually counts.
//
// The belief it corrects: that NumDelivered is a ladder counter the handler
// drives — one increment per failed attempt, so "delivery 7 of 7" means the
// handler tried seven times. It is not. It counts DELIVERIES, and the server
// makes one every time AckWait expires, whatever the handler did or did not do.
// This test disposes of nothing at all — the shape of a handler that blocked,
// crashed, lost its connection, or (per COR-1257's "client death") had its pod
// killed mid-flight — and the count still climbs to MaxDeliver on the server's
// clock alone.
//
// Two consequences the fake cannot show. backoff.NumDelivered and
// backoff.IsFinalDelivery read this same inflated number, so a handler can be
// handed a message that is ALREADY final on its first invocation, and with
// TermOnExhaustion set it will Term after one real attempt. And the elapsed time
// between first and last delivery is a function of AckWait, not of any ladder the
// consumer configured — so reconstructing "which attempt is this" from wall-clock
// spacing (the ENT-1535 log-timing analysis) does not work.
func TestNumDeliveredInflatesWithoutHandlerInvolvement(t *testing.T) {
	t.Parallel()
	_, js := env(t)
	const maxDeliver = 4
	cons := newConsumer(t, js, "events", jetstream.ConsumerConfig{
		Durable:       "inflater",
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       shortAckWait,
		MaxDeliver:    maxDeliver,
		FilterSubject: "events.repo",
	})
	publish(t, js, "events.repo", "never disposed")

	start := time.Now()
	r := consume(t, cons, nil) // no Ack, no Nak, no Term, no InProgress
	got := r.waitForN(t, maxDeliver)
	elapsed := time.Since(start)

	for i, d := range got[:maxDeliver] {
		if want := uint64(i + 1); d.numDelivered != want {
			t.Errorf("delivery %d reported NumDelivered=%d, want %d", i+1, d.numDelivered, want)
		}
		if d.streamSeq != 1 {
			t.Errorf("delivery %d was of stream seq %d, want 1 (the same message)", i+1, d.streamSeq)
		}
	}
	// Consumer sequence increments per delivery even though the stream sequence
	// does not: it is a delivery counter, not a message identifier.
	if got[maxDeliver-1].consumerSeq != uint64(maxDeliver) {
		t.Errorf("final consumer seq = %d, want %d", got[maxDeliver-1].consumerSeq, maxDeliver)
	}
	// The whole ladder ran on AckWait alone. Three waits for four deliveries.
	if min := (maxDeliver - 1) * shortAckWait; elapsed < min-gapEarlySlack {
		t.Errorf("four deliveries in %v, faster than %d AckWait expiries (%v)", elapsed, maxDeliver-1, min)
	}

	// The library's own readers see the inflated count, so the last delivery is
	// "final" to a policy that never saw a handler failure.
	last := fetchAll(t, cons, 1)
	if len(last) != 0 {
		t.Fatalf("MaxDeliver was spent, but a further delivery arrived: %v", meta(t, last[0]))
	}
	if info(t, cons).Delivered.Consumer != uint64(maxDeliver) {
		t.Errorf("Delivered.Consumer = %d, want %d", info(t, cons).Delivered.Consumer, maxDeliver)
	}
}

// TestRedeliveryContinuesOnRepeatedAckWaitWithoutBackOff pins that a consumer with
// no BackOff still has a ladder: AckWait, repeated, MaxDeliver times.
//
// The belief it corrects: that BackOff is what makes a consumer retry, so a
// consumer without one retries once, or not at all, or immediately. Absent BackOff
// is not an absent ladder — it is a FLAT ladder at AckWait, which is the envelope
// every jsconsumer consumer runs today (the scaffold sets AckWait and MaxDeliver
// and never sets BackOff). Sizing a stream's max_age against "the redelivery
// envelope" therefore has to count EffectiveAckWait × EffectiveMaxDeliver even
// when no ladder appears anywhere in the config.
func TestRedeliveryContinuesOnRepeatedAckWaitWithoutBackOff(t *testing.T) {
	t.Parallel()
	_, js := env(t)
	cons := newConsumer(t, js, "events", jetstream.ConsumerConfig{
		Durable:       "flat",
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       shortAckWait,
		MaxDeliver:    4,
		FilterSubject: "events.repo",
		// BackOff deliberately unset.
	})
	publish(t, js, "events.repo", "x")

	r := consume(t, cons, nil)
	got := r.waitForN(t, 4)
	if len(info(t, cons).Config.BackOff) != 0 {
		t.Fatal("the consumer under test has a BackOff ladder; it must have none")
	}
	for i, gap := range gapsBetween(got[:4]) {
		assertGap(t, label("wait before delivery", i+2), gap, shortAckWait)
	}
}

// TestBackOffRungsAreServedBeforeDeliveryN pins the ladder arithmetic, including
// the tail repeat and its off-by-one (COR-1255).
//
// The counting rule, measured: the wait served BEFORE delivery N is
// BackOff[min(N-2, len(BackOff)-1)]. Restated in the terms a config review needs:
//
//   - MaxDeliver deliveries are separated by MaxDeliver-1 waits, so a ladder
//     serves one fewer rung than a reader counting deliveries expects. ENT-1535's
//     7 deliveries over a 6-rung ladder sum to all six rungs (17h45m) — correct
//     precisely because 7-1 == 6.
//   - Once the rungs run out the LAST one repeats for every remaining wait. A
//     3-rung ladder under MaxDeliver=7 serves rungs 0,1,2,2,2,2 — six waits, five
//     of them from an array of three, and the tail rung dominates the envelope.
//   - When MaxDeliver == len(BackOff) the final rung is never served at all: it is
//     dead configuration, and a reviewer summing the array overstates the envelope
//     by that rung.
func TestBackOffRungsAreServedBeforeDeliveryN(t *testing.T) {
	t.Parallel()
	const (
		rung0 = 150 * time.Millisecond
		rung1 = 400 * time.Millisecond
		rung2 = 700 * time.Millisecond
	)
	for _, tc := range []struct {
		name       string
		backOff    []time.Duration
		maxDeliver int
		wantGaps   []time.Duration
	}{
		{
			// The COR-1255 shape: more deliveries than rungs, so the last rung
			// tail-repeats. Five waits from a three-rung array.
			name:       "ladder shorter than MaxDeliver tail-repeats the last rung",
			backOff:    []time.Duration{rung0, rung1, rung2},
			maxDeliver: 6,
			wantGaps:   []time.Duration{rung0, rung1, rung2, rung2, rung2},
		},
		{
			// Equal: MaxDeliver-1 waits means the last rung is never served.
			name:       "ladder equal to MaxDeliver never serves its last rung",
			backOff:    []time.Duration{rung0, rung1, rung2},
			maxDeliver: 3,
			wantGaps:   []time.Duration{rung0, rung1},
		},
		{
			// A single rung is a flat ladder, indistinguishable from AckWait alone.
			name:       "single-rung ladder is flat",
			backOff:    []time.Duration{rung1},
			maxDeliver: 4,
			wantGaps:   []time.Duration{rung1, rung1, rung1},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			_, js := env(t)
			cons := newConsumer(t, js, "events", jetstream.ConsumerConfig{
				Durable:   "ladder",
				AckPolicy: jetstream.AckExplicitPolicy,
				// AckWait must equal BackOff[0] or the server silently
				// rewrites it; see REDACTED.
				AckWait:       tc.backOff[0],
				BackOff:       tc.backOff,
				MaxDeliver:    tc.maxDeliver,
				FilterSubject: "events.repo",
			})
			publish(t, js, "events.repo", "x")

			r := consume(t, cons, nil) // no disposition: the ladder runs on the server's clock
			got := r.waitForN(t, tc.maxDeliver)
			if len(got) > tc.maxDeliver {
				t.Errorf("saw %d deliveries, want MaxDeliver=%d", len(got), tc.maxDeliver)
			}
			gaps := gapsBetween(got[:tc.maxDeliver])
			if len(gaps) != len(tc.wantGaps) {
				t.Fatalf("%d waits between %d deliveries, want %d", len(gaps), tc.maxDeliver, len(tc.wantGaps))
			}
			for i, want := range tc.wantGaps {
				assertGap(t, label("wait before delivery", i+2), gaps[i], want)
			}
		})
	}
}

// TestBackOffGovernsAckTimeoutsNotNakDelays pins the interaction between a
// server-side BackOff ladder and the client-side NakWithDelay that backoff.Policy
// issues — the belief that cost the most review time, because the two look like
// the same mechanism and are not.
//
// BackOff does not govern Nak. It governs how long the server waits for an ack
// before redelivering. Measured, the three dispositions a handler can choose are:
//
//   - plain Nak: redeliver NOW. The ladder is skipped entirely, so a handler that
//     Naks on a transient failure retries at wire speed and burns MaxDeliver in
//     milliseconds — the opposite of what a configured ladder promises.
//   - NakWithDelay(d): redeliver after d + (BackOff[rung] - BackOff[0]). The
//     server offsets the delivery timestamp by d but still measures it against the
//     current RUNG, so the requested delay is stretched by however much the ladder
//     has grown. On a flat ladder the stretch is zero and d is honoured exactly,
//     which is why a flat-ladder test cannot see this.
//   - no disposition at all: redeliver on the rung, exactly as configured. Doing
//     nothing is what actually follows the ladder.
//
// So a growing ladder and backoff.Policy's NakWithDelay do not compose: the policy
// cannot express its own envelope on a consumer that has one. This is the
// arithmetic behind ENT-1535's unexplained retry spacing ("the first two are ~78s
// apart" against a ladder whose first rung is 5m).
func TestBackOffGovernsAckTimeoutsNotNakDelays(t *testing.T) {
	t.Parallel()
	const (
		rung0    = 200 * time.Millisecond
		rung1    = 900 * time.Millisecond
		nakDelay = 100 * time.Millisecond
	)
	// The stretch: rung1 - rung0 added to every requested delay from the second
	// wait onward.
	stretched := nakDelay + (rung1 - rung0)

	for _, tc := range []struct {
		name     string
		dispose  func(jetstream.Msg) error
		wantGaps []time.Duration
	}{
		{
			name:    "plain Nak ignores the ladder and redelivers immediately",
			dispose: func(m jetstream.Msg) error { return m.Nak() },
			// 0 marks "immediate" — asserted with assertImmediate.
			wantGaps: []time.Duration{0, 0, 0},
		},
		{
			name:    "NakWithDelay is stretched by the ladder's growth",
			dispose: func(m jetstream.Msg) error { return m.NakWithDelay(nakDelay) },
			// Before delivery 2 the consumer is still on rung 0, so there is
			// nothing to stretch; from delivery 3 the rung has grown.
			wantGaps: []time.Duration{nakDelay, stretched, stretched},
		},
		{
			name:     "no disposition follows the ladder exactly",
			dispose:  nil,
			wantGaps: []time.Duration{rung0, rung1, rung1},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			_, js := env(t)
			cons := newConsumer(t, js, "events", jetstream.ConsumerConfig{
				Durable:       "nakladder",
				AckPolicy:     jetstream.AckExplicitPolicy,
				AckWait:       rung0,
				BackOff:       []time.Duration{rung0, rung1},
				MaxDeliver:    4,
				FilterSubject: "events.repo",
			})
			publish(t, js, "events.repo", "x")

			var dispose func(jetstream.Msg)
			if tc.dispose != nil {
				dispose = func(m jetstream.Msg) {
					if err := tc.dispose(m); err != nil {
						t.Errorf("dispose: %v", err)
					}
				}
			}
			r := consume(t, cons, dispose)
			got := r.waitForN(t, 4)
			gaps := gapsBetween(got[:4])
			for i, want := range tc.wantGaps {
				lbl := label("wait before delivery", i+2)
				if want == 0 {
					assertImmediate(t, lbl, gaps[i])
					continue
				}
				assertGap(t, lbl, gaps[i], want)
			}
		})
	}
}

// TestBackoffPolicyDelayIsNotWhatTheBrokerServes is the previous test's finding
// stated as a claim about this module's own API, so the composition breaks loudly
// here rather than quietly in a service.
//
// backoff.Policy.DelayFor computes the delay the policy INTENDS. On a consumer
// with a growing server-side BackOff, the broker serves that delay plus the
// ladder's growth. Callers therefore get the policy's envelope only on a consumer
// with no BackOff (or a flat one) — which is how every jsconsumer consumer is
// configured today, and is the assumption this test exists to keep true.
func TestBackoffPolicyDelayIsNotWhatTheBrokerServes(t *testing.T) {
	t.Parallel()
	const (
		rung0 = 200 * time.Millisecond
		rung1 = 900 * time.Millisecond
	)
	policy := backoff.Policy{NakDelay: 100 * time.Millisecond, MaxDeliver: 3}

	for _, tc := range []struct {
		name    string
		backOff []time.Duration
		// wantSecondWait is the gap before delivery 3 — the first wait at which a
		// growing ladder has anything to stretch.
		wantSecondWait time.Duration
	}{
		{
			name:           "no ladder: the policy's delay is served as written",
			backOff:        nil,
			wantSecondWait: policy.NakDelay,
		},
		{
			name:           "growing ladder: the broker serves the policy's delay plus the ladder's growth",
			backOff:        []time.Duration{rung0, rung1},
			wantSecondWait: policy.NakDelay + (rung1 - rung0),
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			_, js := env(t)
			cfg := jetstream.ConsumerConfig{
				Durable:       "policy",
				AckPolicy:     jetstream.AckExplicitPolicy,
				AckWait:       rung0,
				MaxDeliver:    policy.MaxDeliver,
				FilterSubject: "events.repo",
			}
			if tc.backOff != nil {
				cfg.BackOff = tc.backOff
			}
			cons := newConsumer(t, js, "events", cfg)
			publish(t, js, "events.repo", "x")

			r := consume(t, cons, func(m jetstream.Msg) {
				// Exactly what a consumer using the policy does on a transient
				// failure, final delivery included.
				if _, err := policy.NakOrTerm(m); err != nil {
					t.Errorf("NakOrTerm: %v", err)
				}
			})
			got := r.waitForN(t, policy.MaxDeliver)
			gaps := gapsBetween(got[:policy.MaxDeliver])

			// The policy computes the same flat delay for every delivery...
			if got := policy.DelayFor(2); got != policy.NakDelay {
				t.Fatalf("policy.DelayFor(2) = %v, want %v (flat policy)", got, policy.NakDelay)
			}
			// ...but only one of these consumers actually serves it.
			assertGap(t, "wait before delivery 2", gaps[0], policy.NakDelay)
			assertGap(t, "wait before delivery 3", gaps[1], tc.wantSecondWait)
		})
	}
}

// label formats a ladder position for an assertion message: "wait before delivery 3".
func label(prefix string, n int) string {
	return prefix + " " + itoa(n)
}

func itoa(n int) string {
	if n < 10 {
		return string(rune('0' + n))
	}
	return string(rune('0'+n/10)) + string(rune('0'+n%10))
}

