func TestBlockerIsNotDerivableFromAckFloorConsumerSequence(t *testing.T) {
	t.Parallel()
	_, js := env(t)
	// A filtered consumer, because that is how every jsconsumer consumer is
	// configured: the stream sequences it never sees still count in the floor.
	cons := newConsumer(t, js, "events", jetstream.ConsumerConfig{
		Durable:       "identity",
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       shortAckWait,
		MaxDeliver:    20,
		FilterSubject: "events.repo",
	})
	// Interleave subjects this consumer does not match, so the blocking stream
	// sequence is not the blocking delivery number.
	publish(t, js, "events.other", "skip")
	publish(t, js, "events.repo", "blocker")
	publish(t, js, "events.other", "skip")
	publish(t, js, "events.repo", "healthy")

	const blockerStreamSeq = 2
	r := consume(t, cons, func(m jetstream.Msg) {
		if string(m.Data()) != "blocker" {
			if err := m.Ack(); err != nil {
				t.Errorf("ack: %v", err)
			}
		}
	})
	// Let the blocker redeliver several times.
	r.waitForN(t, 4)
	time.Sleep(settleWait)

	ci := info(t, cons)
	if got := ci.AckFloor.Stream + 1; got != blockerStreamSeq {
		t.Errorf("AckFloor.Stream+1 = %d, want the blocker's stream seq %d", got, blockerStreamSeq)
	}
	// The blocker is on its Nth delivery; the consumer floor is still at its first.
	var maxConsumerSeq uint64
	for _, d := range r.snapshot() {
		if d.streamSeq == blockerStreamSeq && d.consumerSeq > maxConsumerSeq {
			maxConsumerSeq = d.consumerSeq
		}
	}
	if maxConsumerSeq <= ci.AckFloor.Consumer+1 {
		t.Fatalf("blocker's latest delivery (consumer seq %d) did not outrun AckFloor.Consumer+1 (%d); "+
			"the test needs more redeliveries to demonstrate staleness", maxConsumerSeq, ci.AckFloor.Consumer+1)
	}
	t.Logf("blocker at stream seq %d is on consumer seq %d, while AckFloor.Consumer+1 reads %d",
		blockerStreamSeq, maxConsumerSeq, ci.AckFloor.Consumer+1)
}

