gofmt -w internal/brokersemantics/ && go test ./internal/brokersemantics/ -run 'TestNonPositiveMaxDeliver|TestJSConsumerDefaults|TestAckWaitIsNormalized|TestBackOffLongerThan|TestStreamConsumerLimits' 2>&1 | tail -25

